# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAMİYET\'İN TEMEL İNANÇ ESASLARI (USÛL-İ DİN / ÂMENTÜ)</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Tevhid (Allah\'a İman)</text>\n  <text x="40" y="103" font-size="11" fill="#334155">• İslam inancının özüdür.</text>\n  <text x="40" y="125" font-size="11" fill="#334155">• Allah zatında, sıfatlarında</text>\n  <text x="50" y="142" font-size="10.5" fill="#475569">ve fiillerinde bir ve tektir.</text>\n  <text x="40" y="165" font-size="11" fill="#334155">• Doğmamış, doğurmamıştır;</text>\n  <text x="50" y="182" font-size="10.5" fill="#475569">şirk (ortak koşma) en büyük</text>\n  <text x="50" y="199" font-size="10.5" fill="#475569">zulüm kabul edilir (İhlâs, 1-4).</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Nübüvvet ve Vahiy</text>\n  <text x="262" y="103" font-size="11" fill="#334155">• Meleklere İman: Cebrail (vahiy)</text>\n  <text x="262" y="125" font-size="11" fill="#334155">• İlahi Vahiylere İman: Suhuf,</text>\n  <text x="272" y="142" font-size="10.5" fill="#475569">Tevrat, Zebur, İncil, Kur\'an.</text>\n  <text x="262" y="165" font-size="11" fill="#334155">• Peygamberlere İman: Hz. Âdem</text>\n  <text x="272" y="182" font-size="10.5" fill="#475569">ilk, Hz. Muhammed (s.a.v.)</text>\n  <text x="272" y="199" font-size="10.5" fill="#475569">son peygamberdir (Hâtemü\'l-Enbiyâ).</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Ahiret ve Kader</text>\n  <text x="485" y="103" font-size="11" fill="#334155">• Ahirete İman: Ba\'s (diriliş),</text>\n  <text x="495" y="120" font-size="10.5" fill="#475569">haşir, mizan, cennet ve cehennem</text>\n  <text x="495" y="137" font-size="10.5" fill="#475569">dünya hayatını anlamlandırır.</text>\n  <text x="485" y="162" font-size="11" fill="#334155">• Kader ve Kazaya İman:</text>\n  <text x="495" y="179" font-size="10.5" fill="#475569">İlahi ölçü ile insanın cüz\'î</text>\n  <text x="495" y="196" font-size="10.5" fill="#475569">irade ve sorumluluk dengesi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAMİYET\'İN TEMEL KAYNAKLARI VE İBADET SİSTEMİ</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kur\'an-ı Kerim ve Sünnet</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• Kur\'an-ı Kerim: Son ilahi vahiydir;</text>\n  <text x="60" y="120" font-size="10.5" fill="#475569">23 yılda peyderpey indirilmiş, hiçbir</text>\n  <text x="60" y="137" font-size="10.5" fill="#475569">değişikliğe (tahrife) uğramadan korunmuştur.</text>\n  <text x="50" y="162" font-size="11" fill="#334155">• Sünnet: Hz. Peygamber\'in Kur\'an\'ı</text>\n  <text x="60" y="179" font-size="10.5" fill="#475569">açıklayan ve hayata geçiren söz, fiil</text>\n  <text x="60" y="196" font-size="10.5" fill="#475569">ve onaylarıdır (İkinci temel kaynak).</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Temel İbadetler (İslam\'ın Şartları)</text>\n  <text x="380" y="103" font-size="11" fill="#334155">• Kelime-i Şehâdet: İmanın ikrarı</text>\n  <text x="380" y="125" font-size="11" fill="#334155">• Namaz (Salât): Günde 5 vakit bedenî ibadet</text>\n  <text x="380" y="147" font-size="11" fill="#334155">• Oruç (Savm): Ramazan ayında irade eğitimi</text>\n  <text x="380" y="169" font-size="11" fill="#334155">• Zekât: Malî ibadet ve sosyal adalet köprüsü</text>\n  <text x="380" y="191" font-size="11" fill="#334155">• Hac: Hem bedenî hem malî ümmet buluşması</text>\n  <text x="515" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Allah ile kul arasında aracı kurum/ruhban yoktur</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAMİYET\'İN AYIRT EDİCİ ÖZELLİKLERİ VE EVRENSEL MESAJI</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Fıtrat ve Vasat Ümmet</text>\n  <text x="40" y="105" font-size="11" fill="#334155">• Fıtrat Dini (Rûm, 30):</text>\n  <text x="50" y="122" font-size="10.5" fill="#475569">İnsanın yaratılış doğasına ve</text>\n  <text x="50" y="139" font-size="10.5" fill="#475569">aklına tam uyumludur.</text>\n  <text x="40" y="165" font-size="11" fill="#334155">• İtidal (Vasat Ümmet):</text>\n  <text x="50" y="182" font-size="10.5" fill="#475569">Dünya ve ahiret, madde ve</text>\n  <text x="50" y="199" font-size="10.5" fill="#475569">mana arasında denge kurar.</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ruhbanlığın Olmayışı</text>\n  <text x="262" y="105" font-size="11" fill="#334155">• Günah çıkarma ve din adamı</text>\n  <text x="272" y="122" font-size="10.5" fill="#475569">sınıfı (ruhbanlık) yoktur.</text>\n  <text x="262" y="148" font-size="11" fill="#334155">• Aslî günah inancı reddedilir;</text>\n  <text x="272" y="165" font-size="10.5" fill="#475569">her insan tertemiz (günahsız)</text>\n  <text x="272" y="182" font-size="10.5" fill="#475569">doğar ve kendi eyleminden</text>\n  <text x="272" y="199" font-size="10.5" fill="#475569">bireysel olarak sorumludur.</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Evrensellik ve Barış</text>\n  <text x="485" y="105" font-size="11" fill="#334155">• Belirli bir ırka veya zümreye</text>\n  <text x="495" y="122" font-size="10.5" fill="#475569">değil, tüm insanlığa hitap eder.</text>\n  <text x="485" y="148" font-size="11" fill="#334155">• Üstünlük soy ve zenginlikte</text>\n  <text x="495" y="165" font-size="10.5" fill="#475569">değil, takvadadır (Hucurât, 13).</text>\n  <text x="485" y="190" font-size="11" fill="#334155">• Din ve vicdan özgürlüğü</text>\n  <text x="495" y="207" font-size="10.5" fill="#475569">(Bakara, 256) güvence altındadır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
